import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第六十二章 说法要让人能够听的懂","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/62第六十二章 说法要让人能够听的懂.md","filePath":"meditation/巴利文大藏经/62第六十二章 说法要让人能够听的懂.md"}'),o={name:"meditation/巴利文大藏经/62第六十二章 说法要让人能够听的懂.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第六十二章-说法要让人能够听的懂" tabindex="-1">第六十二章 说法要让人能够听的懂 <a class="header-anchor" href="#第六十二章-说法要让人能够听的懂" aria-label="Permalink to &quot;第六十二章 说法要让人能够听的懂&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部12相应32经/黑齿经(因缘相应/因缘篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园。有一天，有个叫伽拉罗的王族出家人来到舍利弗尊者的住处，他与舍利弗尊者互相问候后，就在一旁坐下，伽拉罗对舍利弗尊者说：“舍利弗学友，我听说摩利亚帕辜那比丘（出家人）已经不再修行了，他已经还俗了。摩利亚帕辜那出家后受持戒律，按如来的正法去修行，他没有让内心得到安宁，他没有解除心中的困惑。</p><p>舍利弗学友，您受持戒律，按如来的正法去修行，让内心得到安宁了吗？您由此解除了心中的疑惑了吗？”</p><p>舍利弗尊者回答：“伽拉罗学友，我受持如来制定的戒律，我按如来的正法去修行，内心已经没有任何的困惑。”</p><p>伽拉罗比丘说：“舍利弗学友，那以后呢？您以后、未来修行能够一直没有困惑吗？”</p><p>舍利弗尊者回答：“伽拉罗学友，我以后、未来也不会有困惑。”</p><p>与舍利弗尊者简短的交谈后，伽拉罗比丘就离开舍利弗尊者来到佛陀的住所，他顶礼佛陀后，就在一旁坐下，伽拉罗比丘对佛陀说：“世尊，舍利弗尊者以彻底完全解脱的智慧说到：「我已经了知：我从这一世开始就已经不会再继续的投生了，我身体行为，口说言语，内心念想的修行已经圆满，应该做的事情已经做好，我不会再出生在这个世间了，我不会再有生死轮回的状态了。」”</p><p>佛陀听完伽拉罗比丘的言语，就叫来一位出家弟子说到：“比丘！你到舍利弗的住处对他说：「舍利弗尊者，如来请你到他的住处去」。”</p><p>这位比丘回答：“世尊，我现在就去叫舍利弗尊者到您这里来。”那位比丘于是就来到舍利弗尊者的住处，他对舍利弗尊者说：“舍利弗尊者！如来让您去他的住处。他好像有些事情要问您。”</p><p>舍利弗尊者回答：“比丘，好的，我知道了，我们一同去见世尊吧。”舍利弗尊者就与这位比丘一同前往佛陀的住处，到达佛陀的住所后，舍利弗尊者就顶礼佛陀，在一旁坐下。佛陀对舍利弗尊者说：“舍利弗，你曾经说过这样的话吗？「我已经了知：我从这一世开始已经不会再继续的投生了，我身体行为，口说言语，内心念想的修行已经圆满，应该做的事情已经做好，我不会再出生在这个世间了，我不会再有生死轮回的状态了。你真的说过这些言语吗？”</p><p>舍利弗尊者看见伽拉罗比丘坐在佛陀的身边，于是他就回答佛陀：“世尊，我不是用这样的言语表达的，我是用另外的言语表达的。”</p><p>佛陀说：“舍利弗，修行人以彻底完全的智慧来说明他们已经证悟解脱的果位，不管他们用什么样的言语来表达，其实他们要表达的意思是一样的，和刚才如来说的那句话所表达出来的解脱境界是一样的。”</p><p>舍利弗尊者回答：“世尊，就算我不是说的这句话，说的是其他的话，表达的也是同一个意思吗？世尊，我不会这样说的。”</p><p>佛陀说：“舍利弗，如果你被别人问：你如何表达已经证悟解脱果位的境界和状态呢？你应该如何回答他们呢？”</p><p>舍利弗尊者回答：“世尊，如果我被别人问证悟解脱果位的境界和状态，我会用缘起法（缘起法解释，见第四十八章、第四十九章）来回答他们，世尊，我会这样的回答他们：学友，出生在世间的前提条件灭尽了，我就知道：当「生」的前提条件被灭尽的时候，「生」就不会有结果了，就会被灭尽了。知道了「生」的结果被灭尽后，我就知道了：我不会再继续的投生，我的修行已经圆满，应该做的事情已经做好，我不会再出生在这个世间，不会再有生死轮回的状态了。世尊，我会这样回答他们的问题的。”</p><p>佛陀说：“舍利弗，如果他们又这样的问你：舍利弗学友，「生」产生的前提条件是什么呢？「生」的起因是什么呢？「生」是依靠什么而出现发生的呢？「生」的根源是什么？舍利弗，当别人这样问你的时候，你应该如何回答他们呢？”</p><p>舍利弗尊者回答：“世尊，如果他们问我「生」产生的前提条件是什么呢？「生」的起因是什么呢？「生」是依靠什么而出现发生的呢？「生」的根源是什么？我就会这样的回答他们：学友，「有」是「生」产生的前提条件，「有」是「生」的起因，「生」依靠「有」出现发生，「有」是「生」的根源。世尊，我会这样的回答他们。”</p><p>佛陀说：“舍利弗，如果他们这样问你：学友，「有」产生的前提条件是什么呢？「有」的起因是什么呢？「有」是依靠什么而出现发生的呢？「有」的根源是什么？舍利弗，他们如果这样问你，你应该如何回答呢？”</p><p>舍利弗尊者回答：“世尊，如果他们问我「有」产生的前提条件是什么呢？「有」的起因是什么呢？「有」是依靠什么而出现发生的呢？「有」的根源是什么？我就会这样的回答：学友，「取」是「有」产生的前提条件，「取」是「有」的起因，「有」依靠「取」出现发生，「取」是「有」的根源。世尊，我会这样的回答他们。”</p><p>佛陀说：“舍利弗，如果他们这样问你：学友，「取」产生的前提条件是什么呢？「取」的起因是什么呢？「取」是依靠什么而出现发生的呢？「取」的根源是什么？舍利弗，他们如果这样问你，你该如何回答？”</p><p>舍利弗尊者回答：“世尊，如果他们问我「取」产生的前提条件是什么呢？「取」的起因是什么呢？「取」是依靠什么而出现发生的呢？「取」的根源是什么？我就会这样的回答：学友，「爱」是「取」产生的前提条件，「爱」是「取」的起因，「取」依靠「爱」出现发生，「爱」是「取」的根源。世尊，我会这样的回答他们。”</p><p>佛陀说：“舍利弗，如果他们这样问你：学友，「爱」产生的前提条件是什么呢？「爱」的起因是什么呢？「爱」是依靠什么而出现发生的呢？「爱」的根源是什么？舍利弗，他们如果这样问你，你该如何回答？”</p><p>舍利弗尊者回答：“世尊，如果他们问我「爱」产生的前提条件是什么呢？「爱」的起因是什么呢？「爱」是依靠什么而出现发生的呢？「爱」的根源是什么？我就会这样的回答：学友，「受」是「爱」产生的前提条件，「受」是「爱」的起因，「爱」依靠「受」出现发生，「受」是「爱」的根源。世尊，我会这样的回答他们。”</p><p>佛陀说：“舍利弗，如果他们这样问你：学友，如何知道，你不会被这些感受所捆绑和束缚呢？如何知道你不会沉迷在这些感受之中呢？舍利弗，他们如果这样问你，你该如何回答？”</p><p>舍利弗尊者回答：“世尊，如果他们问我：如何知道，我不会被这些感受束缚捆绑，如何知道我不会沉迷在这些感受之中？我会这样的回答他们：学友，有三种感受，是哪三种感受呢？就是快乐的感受，痛苦的感受，不苦不乐的感受。学友这三种感受是无常的，是随时都在变化的，是无法永远保持不变的，是无法永恒存在的。这样就知道了只要是无常的事物，最终给自己带来的就是痛苦的感受，为什么呢？当拥有得到自己喜欢的事物，就会产生快乐的感受，当这些事物衰败、灭亡、消失的时候，之前拥有获得这些事物时产生了多大的快乐，当这些事物衰败、灭亡、消失的时候就会给自己带来多大的痛苦，因为世间任何的事物都不可能永远的保持不变，都不可能永恒的存在，他们随时都在变化。所以无常的事物，最终给自己带来的都是痛苦的感受。而不苦不乐的感受为什么也会产生痛苦呢？因为世间的每一个人都会死去，所以不苦不乐的感受那是不长久的，是无法永远保持不变的，是无法永恒存在的，每个人临死前，就会更加深刻的明白：自己死后要舍弃所有的财物，要离开自己的家人、亲人，那种临死前依依不舍的心情，那种对死亡的恐怖，被死亡病痛折磨的感受也是非常痛苦的。所以不苦不乐最终也会是痛苦的感受。出生在世间的人最终都是痛苦的，因为世间的人随时都在变化，无法青春永驻，无法长生不死，是无常的，所以世间的人最终都是痛苦的。世尊，就是因为我已经明白了世间的无常，所以就不会被这些随时在变化的感受所束缚捆绑，就不会沉迷在这些随时在变化的感受之中，因为我知道世间一切的感受最终都是痛苦的，如果被它们束缚捆绑，如果我沉迷在这些感受之中，我就会在烦恼和痛苦中挣扎，无法解脱出来。世尊，我会这样的回答他们的问题的。”</p><p>佛陀说：“舍利弗，你回答的好！很不错！舍利弗，你刚才说的法理，可以简要的说成：「一切的感受最终都是痛苦的」。舍利弗，如果别人问你，那如何才能从世间的一切烦恼和痛苦中解脱出来呢？如何才能证悟解脱的果位呢？舍利弗你应该如何回答他们的问题呢？”</p><p>舍利弗尊者回答：“世尊，如果他们问我：如何才能从世间的一切烦恼和痛苦中解脱出来呢？如何才能证悟解脱的果位呢？我就会这样的回答他们：我修行八正道（八正道解释，见第十八章）来除灭一切的烦恼和痛苦，来消除我做恶事造下的一切罪业。这样我的烦恼和痛苦就能逐渐的被消除、灭尽，我造下的罪业也能逐渐的被消除殆尽。到最后我连善恶、福德罪恶、功德罪业都不会再挂念和执着了，对这个所谓的我都不会再挂念和执着了。我不会再挂念和执着世间一切的事物，我不会再挂念和执着内心一切的念想，我将自己对世间一切的挂念和执着都灭除殆尽了，这样烦恼和痛苦就无法在我的内心中流动。这样我就从世间一切的烦恼和痛苦中解脱了出来，这样我就能证悟解脱的果位。世尊，我会这样回答他们的问题的。”</p><p>佛陀说：“舍利弗，你回答的很好！舍利弗你刚才回答的法理可以简要的说成：「任何的修行人，当他们明白了世间的真相、规则后，他们就能明白世间烦恼和痛苦产生的根源，他们就不会有任何的困惑。他们没有困惑后，就不会再挂念和执着世间这个所谓的我，他们就不会认为这个我是真实永恒存在的，他们对世间这个我的挂念和执着灭尽了，就从一切的烦恼和痛苦中解脱了出来，就证悟了解脱的果位」。”</p><p>佛陀说法后，就从座位上站起来，进入卧室开始静坐。佛陀离开后不久，舍利弗尊者就对听法的伽拉罗比丘，以及其他在场听法的出家人说：“学友们，当世尊，问我第一个问题的时候，我还不知道该如何的回答。但是当世尊多次的问我问题后，我就按着世尊之前教导给我的修行方法去回答他提出来的问题，后来我回答世尊的问题就轻车熟路了，所以我认为法是不可以拘泥于言语的，只要已经开启了智慧，证悟了解脱的果位，就应该按自己实际的真实体悟去回答别人的问题，我之前畏畏缩缩的回答世尊的问题，生怕自己说错了，其实这也是对法的挂念和执着。到后来，我回答世尊的问题，完全以自己的真实体悟来回答，就完全舍离、抛弃了对法的挂念和执着，因为那些修行的体悟都是我自己真实的修行感悟。世尊在问我问题的时候，我好像在与自己对话，自问自答，完全没有之前的那种拘束和担心，也从对法的挂念和执着中解脱了出来。世尊如果问我一天一夜的问题，我就会一天一夜的回答世尊的问题，世尊如果问我两天两夜的问题，我也会回答世尊两天两夜的问题，甚至于世尊如果问我三天三夜、四天四夜、五天五夜、六天六夜、七天七夜的问题，我也将会三天三夜、四天四夜、五天五夜、六天六夜、七天七夜的回答世尊的问题的。学友们，因为我受持世尊制定的戒律，我按世尊所说的法去修行，在修行的过程中我开启了智慧，体会到了解脱的境界，我就按我真实的体悟和修行达到的境界，来回答世尊的问题。学友们，不可拘泥于法，不可挂念和执着法，自己是什么样的体悟，自己达到了什么样的解脱境界，就如实的按自己达到的解脱境界来回答别人提出来的问题。解说的言语、词汇，以及说法的方式这些都是可以根据听法的人或自己的实际情况来调整和变化的，不可拘泥于说法的言语、词汇，以及说法的方式，只要自己说法能够让听法的人明白自己表达出来的法理就可以了，当然如实的对别人说自己真实的修行体会，真实达到的解脱境界。如实的对别人说自己是如何修行达到这些解脱境界、解脱果位的，这个很重要，要简单明了的为别人解说。以听法的人能够听懂来判断说法的好坏。别人能够听懂自己所说的法理，那就是最好的开示、宣说。别人无法听懂自己所说的法理，就算说法的时候用了再华丽漂亮的词汇、言语都没有起到作用，都是很不好、很差的说法。以自己真实的修行体悟，以简单明了能够让人听懂的言语作为自己说法的前提。”</p><p>伽拉罗比丘和在座的出家人都异口同声的说：“舍利弗尊者，已经彻底的证悟了解脱的果位，舍利弗尊者说法犹如狮子王在吼叫，让森林中的其他飞禽走兽都为之震惊。我们听舍利弗尊者说法内心被震动开启了智慧，他说要按自己真实的修行体会去说法，不可拘泥于言语、词汇，以及说法的方式。要以自己真实的修行体会，要以听法的人能够听懂自己所说的法理做为说法的前提。我们感谢舍利弗尊者为我们说法，我们明白了对法的挂念和执着也是一种烦恼和痛苦，我们也赞叹世尊为我们说法的无量功德，我们会继续的受持世尊制定的戒律，我们也会继续的按佛陀的正法去修行的。</p>',32)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
